package servicio;
import api.publica.PagoClienteDTO.CapacidadesPago;import config.ConfiguracionMercadoPago;
public class CapacidadesPagoService {private final ConfiguracionMercadoPago mercadoPago;private final pagos.PasarelaPagoOnline pasarela;public CapacidadesPagoService(){this(ConfiguracionMercadoPago.cargar());}public CapacidadesPagoService(ConfiguracionMercadoPago c){this(c,pagos.PasarelaPagoFactory.crear(c));}CapacidadesPagoService(ConfiguracionMercadoPago c,pagos.PasarelaPagoOnline p){mercadoPago=c;pasarela=p;}public CapacidadesPago obtener(){boolean online=mercadoPago!=null&&mercadoPago.seguraParaPublicar()&&pasarela!=null&&pasarela.disponible();return new CapacidadesPago("ARS",online,true,online?"MERCADO_PAGO":null,"MANUAL",true,true);}}
